"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/sparkline.css";
import type { CSSProperties, SVGProps } from "react";
import { cn } from "../../lib/cn";
import {
  createAnalyticsAreaPath,
  createAnalyticsPath,
  getAnalyticsDomain,
  type AnalyticsSeriesTone,
} from "../../lib/analytics";

export type SparklineProps = Omit<SVGProps<SVGSVGElement>, "children" | "width" | "height" | "fill" | "values"> & {
  values: readonly (number | null)[];
  label?: string;
  width?: number;
  height?: number;
  tone?: AnalyticsSeriesTone;
  fill?: boolean;
  decorative?: boolean;
};

export function Sparkline({
  values,
  label = "Trend",
  width = 112,
  height = 32,
  tone = "primary",
  fill = false,
  decorative = false,
  className,
  style,
  ...props
}: SparklineProps) {
  const data = values.map((value, index) => ({ id: String(index), label: String(index + 1), values: { value } }));
  const domain = getAnalyticsDomain(data, ["value"], { paddingRatio: 0.12 });
  const box = { width, height, left: 1.5, right: 1.5, top: 2, bottom: 2 };
  const path = createAnalyticsPath(data, "value", domain, box);
  const areaPath = fill ? createAnalyticsAreaPath(data, "value", domain, box) : "";
  const sparklineStyle = { ...style, "--whatiuse-sparkline-width": `${width}px`, "--whatiuse-sparkline-height": `${height}px` } as CSSProperties;

  return (
    <svg
      className={cn("whatiuse-sparkline", className)}
      data-tone={tone}
      viewBox={`0 0 ${width} ${height}`}
      preserveAspectRatio="none"
      width={width}
      height={height}
      role={decorative ? undefined : "img"}
      aria-label={decorative ? undefined : label}
      aria-hidden={decorative || undefined}
      focusable="false"
      style={sparklineStyle}
      {...props}
    >
      {areaPath && <path className="whatiuse-sparkline__area" d={areaPath} />}
      {path ? <path className="whatiuse-sparkline__line" d={path} pathLength={1} /> : <line className="whatiuse-sparkline__empty" x1="0" x2={width} y1={height / 2} y2={height / 2} />}
    </svg>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-sparkline {
  display: block;
  flex: none;
  width: var(--whatiuse-sparkline-width);
  height: var(--whatiuse-sparkline-height);
  overflow: visible;
  color: var(--whatiuse-fg-default);
}

.whatiuse-sparkline[data-tone="secondary"] { color: var(--whatiuse-fg-muted); }

.whatiuse-sparkline[data-tone="tertiary"] { color: var(--whatiuse-fg-subtle); }

.whatiuse-sparkline__line,
.whatiuse-sparkline__empty {
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}

.whatiuse-sparkline__area { fill: currentColor; opacity: .075; }

.whatiuse-sparkline__empty { opacity: .24; stroke-dasharray: 2 3; }
}
